import{_ as i,c as o,o as e,aj as a}from"./chunks/framework.rJ-FfUda.js";const c=JSON.parse('{"title":"hadoop","description":"","frontmatter":{"title":"hadoop","hugoSource":"computer-science/big-data/hadoop.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/big-data/2026-11-17-hadoop.md","filePath":"computer-science/big-data/2026-11-17-hadoop.md"}'),t={name:"computer-science/big-data/2026-11-17-hadoop.md"};function r(u,l,n,s,d,p){return e(),o("div",null,[...l[0]||(l[0]=[a('<h1 id="hadoop" tabindex="-1">hadoop <a class="header-anchor" href="#hadoop" aria-label="Permalink to “hadoop”">​</a></h1><ul><li>Hadoop生态系统是一个由Apache基金会维护的开源软件集合，用于处理和分析大规模数据集。经过多年发展，Hadoop已从最初的HDFS和MapReduce两个核心组件扩展为一个包含众多工具和框架的完整生态系统</li><li>核心基础组件 <ul><li><strong>HDFS (Hadoop Distributed File System)</strong><ul><li>Hadoop的分布式文件系统，用于存储超大规模数据集</li><li>采用主从架构：NameNode(主节点)管理元数据，DataNode(从节点)存储实际数据块</li><li>特点：高容错性、高吞吐量、适合部署在廉价硬件上</li></ul></li><li><strong>YARN (Yet Another Resource Negotiator)</strong><ul><li>Hadoop 2.0引入的资源管理和作业调度框架</li><li>包含ResourceManager(集群资源管理)和NodeManager(节点资源监控)</li><li>支持多种计算框架(MapReduce、Spark等)共享集群资源</li></ul></li><li><strong>MapReduce</strong><ul><li>分布式计算框架，采用&quot;分而治之&quot;思想</li><li>包含Map(数据分解)和Reduce(结果汇总)两个阶段</li><li>适合处理大规模离线批处理任务</li></ul></li></ul></li><li>数据存储组件 <ul><li><strong>HBase</strong><ul><li>分布式列式NoSQL数据库，基于Google BigTable设计</li><li>构建在HDFS之上，提供实时读写能力</li><li>适合存储海量结构化数据</li></ul></li><li><strong>Hive</strong><ul><li>数据仓库工具，提供类SQL查询语言(HiveQL)</li><li>将SQL转换为MapReduce/Tez/Spark作业执行</li><li>适合数据汇总、即席查询和分析</li></ul></li><li><strong>Pig</strong><ul><li>高级数据流语言(Pig Latin)和执行框架</li><li>简化MapReduce编程，适合ETL流程</li><li>支持结构化/半结构化数据处理</li></ul></li></ul></li><li>数据采集与传输组件 <ul><li><strong>Sqoop</strong><ul><li>关系型数据库与Hadoop间数据传输工具</li><li>支持从MySQL、Oracle等导入数据到HDFS/Hive/HBase</li><li>也支持将Hadoop数据导出到关系数据库</li></ul></li><li><strong>Flume</strong><ul><li>分布式日志收集系统</li><li>适合采集、聚合和移动大量日志数据到HDFS</li><li>包含Source(数据源)、Channel(传输通道)和Sink(目的地)三个组件</li></ul></li></ul></li><li>协调与管理组件 <ul><li><strong>Zookeeper</strong><ul><li>分布式协调服务</li><li>提供统一命名服务、配置管理、集群同步等</li><li>解决分布式环境下的数据一致性问题</li></ul></li><li><strong>Oozie</strong><ul><li>工作流调度系统</li><li>用于编排Hadoop作业(MapReduce、Pig、Hive等)</li><li>支持定时和依赖触发</li></ul></li><li><strong>Ambari</strong><ul><li>Hadoop集群管理工具</li><li>提供Web界面监控、配置和管理Hadoop集群</li><li>支持大多数Hadoop组件</li></ul></li></ul></li><li>高级计算框架 <ul><li><strong>Spark</strong><ul><li>内存计算框架，比MapReduce快10-100倍</li><li>支持批处理、流处理、机器学习和图计算</li><li>可与HDFS、HBase等集成</li></ul></li><li><strong>Flink</strong><ul><li>流处理框架，支持事件时间和精确一次处理</li><li>适合实时数据分析场景</li><li>与Hadoop生态系统兼容</li></ul></li><li><strong>Mahout</strong><ul><li>机器学习算法库</li><li>提供聚类、分类、推荐等算法实现</li><li>可扩展至大规模数据集</li></ul></li></ul></li><li>其他重要组件 <ul><li><strong>Kafka</strong><ul><li>分布式消息队列系统</li><li>高吞吐量、低延迟</li><li>常用于实时数据管道</li></ul></li><li><strong>Tez</strong><ul><li>优化后的MapReduce执行引擎</li><li>减少中间结果写入磁盘，提高性能</li><li>被Hive、Pig等采用</li></ul></li><li><strong>Avro</strong><ul><li>数据序列化系统</li><li>提供紧凑的二进制数据格式</li><li>支持RPC通信</li></ul></li></ul></li></ul>',2)])])}const H=i(t,[["render",r]]);export{c as __pageData,H as default};
